const nums = [1, 2, 3, 4, 5, 6];
const grouped = nums.reduce((acc, n) => {
  const key = n % 2 === 0 ? 'even' : 'odd';
  acc[key] = acc[key] || [];
  acc[key].push(n);
  return acc;
}, {});
console.log(grouped);
